target.css:
:root {
  --ink: #20303d;
  --muted: #6d7b83;
  --paper: #fffdf8;
  --line: #d8e0dc;
  --mint: #dff3e9;
  --mint-deep: #2e846c;
  --slate: #5b7185;
  --coral: #ed745d;
  --night: #203b48;
}

* {
  box-sizing: border-box;
}

.route-board {
  width: 500px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 14px;
  color: var(--ink);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.board-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.title-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.kicker {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}

.title-block h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1;
  letter-spacing: -0.6px;
}

.live-pill {
  background: var(--mint);
  color: var(--mint-deep);
  border-radius: 999px;
  padding: 7px 10px;
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--mint-deep);
}

.overview {
  display: grid;
  grid-template-columns: 136px 1fr;
  gap: 10px;
}

.wall-map {
  min-height: 70px;
  background: var(--night);
  border-radius: 12px;
  padding: 10px;
  color: var(--paper);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.wall-label {
  color: var(--mint);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.9px;
}

.wall-map strong {
  font-size: 25px;
  line-height: 0.8;
}

.zone-mark {
  align-self: flex-end;
  color: var(--line);
  font-size: 9px;
  font-weight: 700;
}

.shift-summary {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
}

.metric {
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.metric + .metric {
  border-left: 1px solid var(--line);
}

.metric:nth-child(n + 3) {
  border-top: 1px solid var(--line);
}

.metric:nth-child(3) {
  border-left: 0;
}

.metric strong {
  color: var(--ink);
  font-size: 15px;
  line-height: 1;
}

.metric span {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.1;
}

.route-list {
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
}

.list-head {
  background: var(--mint);
  padding: 6px 10px;
  color: var(--mint-deep);
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.routes {
  list-style: none;
  margin: 0;
  padding: 0;
}

.route-item {
  min-height: 38px;
  padding: 6px 10px;
  display: grid;
  grid-template-columns: 42px 1fr auto;
  align-items: center;
  gap: 9px;
}

.route-item + .route-item {
  border-top: 1px solid var(--line);
}

.grade {
  border-radius: 7px;
  padding: 5px 0;
  color: var(--paper);
  text-align: center;
  font-size: 11px;
  font-weight: 800;
}

.grade.slate {
  background: var(--slate);
}

.grade.coral {
  background: var(--coral);
}

.route-info {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.route-info strong {
  font-size: 13px;
  line-height: 1.1;
}

.route-info small {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.1;
}

.hold-count {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.board-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.sync-note {
  color: var(--muted);
  font-size: 10px;
}

.deploy-button {
  border: 0;
  border-radius: 9px;
  padding: 8px 11px;
  background: var(--ink);
  color: var(--paper);
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 11px;
  font-weight: 800;
}

.deploy-button span {
  color: var(--mint);
  font-size: 15px;
  line-height: 0.7;
}

